/* Adds progression and a reference-led shop without replacing the café scene. */
let journey={shift:1,cash:45,owned:[],reports:[],rental:false},shopSelected='syrup';
const campaignStart=start,campaignRender=render,campaignUpdate=update,campaignOpen=openStation,campaignAdvance=advancePour,campaignStationUpdate=updateStation,campaignBaking=openBaking,campaignShowModal=showModal;
start=function(){journey={shift:1,cash:45,owned:[],reports:[],rental:false};campaignStart();};
function beginCampaignShift(){closeModal();document.querySelector('#tutorial-coach')?.remove();document.querySelector('#tutorial-result-card')?.remove();lesson=null;lessonResult=null;sim=new CampaignCafe(journey.shift,journey.owned,journey.cash,journey.rental);journey.rental=false;paused=false;servedAnimation=null;render();toast(['','Shift 1 · Learn and observe the café.','Shift 2 · Test your improvements on the same rush.','Shift 3 · A busier café puts your system to the test.'][journey.shift]);}
// Tutorial feedback stays small and next to the game, including the completion action.
notice=function(title,body,callback,label='Continue'){paused=true;document.querySelector('#tutorial-result-card')?.remove();modalKind='tutorial-result';const e=document.createElement('aside');e.id='tutorial-result-card';e.setAttribute('role','dialog');e.innerHTML=`<h3>${title}</h3><p>${body}</p><button class="big-btn">${label}</button>`;document.body.appendChild(e);e.querySelector('button').onclick=()=>{e.remove();modalKind=null;paused=false;last=performance.now();if(label==='Start the real shift')beginCampaignShift();else callback?.();};positionCoach(e);e.querySelector('button').focus();};
function positionCoach(e){const target=lesson!==null?document.querySelector(lessons[lesson]?.[2]):null,r=target?.getBoundingClientRect();const width=Math.min(270,innerWidth-20);e.style.width=width+'px';e.style.left=Math.max(10,Math.min(innerWidth-width-10,r?r.left-width-15:15))+'px';e.style.top=Math.max(10,Math.min(innerHeight-e.offsetHeight-10,r?r.top:120))+'px';}
const originalTutorialUpdate=tutorialUpdate;
tutorialUpdate=function(){originalTutorialUpdate();const e=document.querySelector('#tutorial-coach');if(e){e.style.visibility=lessonResult?"hidden":"visible";positionCoach(e);}};
render=function(){campaignRender();const dashboard=document.querySelector('.queue-dashboard');dashboard.innerHTML='<div class="live-queue-pair"><span>Queue Length <b id="queue-live">0</b></span><span>Arrival Rate <b id="arrival-live">2/min</b></span></div><button class="helper-button" id="helper">+ Add barista</button><span id="mission-progress" hidden></span><span id="flow-counts" hidden></span>';document.querySelector('#helper').onclick=()=>showModal('helper');document.querySelector('.economy').style.visibility='hidden';update();};
update=function(){campaignUpdate();if(!sim||sim.finished||!document.querySelector('#queue-live'))return;document.querySelector('#queue-live').textContent=sim.orders.length;document.querySelector('#queue-live').parentElement.title='Customers who have arrived but have not received their complete order.';document.querySelector('#arrival-live').textContent=sim.tutorial?'Practice':sim.arrivalRate+'/min';if(!sim.tutorial){document.querySelector('#served-count').textContent=`Shift ${sim.shift}/3 · ${sim.served.length}/${sim.arrivals.length} served`;document.querySelector('#rush-ribbon').hidden=!sim.rushShown;document.querySelector('#rush-ribbon').textContent=`Rush time! ${sim.arrivalRate} customers per minute`;sim.activity=pouring?stationPanel?.key:toppingGesture?'topping':null;document.querySelector('#instruction').textContent=!sim.active?'Waiting for the next customer.':!sim.active.accepted?'Select a customer and take their order.':sim.ready()?'Order ready to hand over.':'Your stations are ready. Choose what to work on next.';document.querySelector('#baking-status').innerHTML=sim.ovenSlots.map((s,i)=>s?`<span>Slot ${i+1} · ${sim.orders.find(o=>o.id===s.id)?.name}: ${s.ready?'Ready to collect':Math.ceil(Math.max(0,s.duration-sim.time+s.started))+'s'}</span>`:'').join('');}updatePopupMetrics();};
function updatePopupMetrics(){const e=document.querySelector('#popup-queue-metrics');if(e)e.textContent=`Queue Length: ${sim.orders.length} · Arrival Rate: ${sim.tutorial?'Practice':sim.arrivalRate+'/min'}`;}
openStation=function(k){campaignOpen(k);if(!stationPanel)return;const overlay=document.querySelector('.station-overlay');if(!document.querySelector('#popup-queue-metrics'))overlay.insertAdjacentHTML('beforeend','<div id="popup-queue-metrics"></div>');if(!sim.tutorial){sim.setupUntil=sim.time+(sim.upgrades.has('layout')?.3:1.5);if(sim.upgrades.has('guide'))overlay.classList.add('upgraded-guide');if(sim.upgrades.has('display')){overlay.querySelectorAll('[data-choice],[data-top-tool],[data-food]').forEach(b=>{const value=b.dataset.choice||b.dataset.topTool||b.dataset.food,expected=sim.active.recipe[k==='baking'?'bakery':k];if(Array.isArray(expected)?expected.includes(value):expected===value){b.classList.add('ticket-match');b.title='Matches this customer’s ticket';}});}}updatePopupMetrics();};
advancePour=function(dt){campaignAdvance(dt*(!sim.tutorial&&sim.upgrades.has(stationPanel?.key)?1.35:1));};
updateStation=function(){campaignStationUpdate();updatePopupMetrics();if(sim&&!sim.tutorial&&stationPanel&&document.querySelector('#dispenser-label')&&sim.time<sim.setupUntil)document.querySelector('#dispenser-label').textContent='Setting up…';};
openBaking=function(){campaignBaking();if(stationPanel?.key!=='baking'||sim.tutorial)return;document.querySelector('.baking-dialog header small').textContent=`${sim.ovenSlots.length} slots · ${sim.upgrades.has('oven')?12:20} seconds each`;if(sim.ovenSlots.length===3){const el=document.createElement('button');el.className='oven-slot';el.dataset.slot='2';el.setAttribute('aria-label','Oven slot 3');document.querySelector('.oven-slots').appendChild(el);el.onclick=()=>{if(sim.ovenSlots[2]?.ready){sim.collectOven(2);update();updateBaking();}else if(!sim.ovenSlots[2])loadFood(2,selectedFood);};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();loadFood(2,e.dataTransfer.getData('text/plain'));};}updateBaking();};
const baseUpdateBaking=updateBaking;
updateBaking=function(){baseUpdateBaking();if(stationPanel?.key!=='baking'||sim.tutorial)return;document.querySelectorAll('[data-slot]').forEach(el=>{const s=sim.ovenSlots[+el.dataset.slot];if(s){el.querySelector('strong').textContent=s.ready?'✓ Collect food':Math.ceil(Math.max(0,s.duration-sim.time+s.started))+' seconds';el.querySelector('i').style.width=Math.min(100,(sim.time-s.started)/s.duration*100)+'%';}});};
showModal=function(kind){if(!sim?.tutorial&&(kind==='helper'||kind==='rush')){paused=true;modalKind=kind;closeStation();const e=document.createElement('div');e.className='modal-backdrop';e.innerHTML=`<section class="modal"><h2>${kind==='rush'?'Here comes the rush!':'Add another barista?'}</h2><p>The café is receiving ${sim.arrivalRate} customers per minute. A second barista prepares accepted, untouched drinks while you handle the other work.</p><p><b>$10 for the rest of this shift.</b> Both baristas share the oven. Available money: $${(sim.cash+sim.profit).toFixed(2)}.</p><button class="big-btn gold" id="decline-helper">Keep working</button><button class="big-btn" id="accept-helper" ${sim.helper?'disabled':''}>${sim.helper?'Already hired':'Hire · $10'}</button></section>`;document.body.appendChild(e);document.querySelector('#decline-helper').onclick=closeModal;document.querySelector('#accept-helper').onclick=()=>{if(sim.hire()){closeModal();update();}else toast('Not enough money to hire another barista.');};return;}campaignShowModal(kind);};
const oldSummary=summary;
summary=function(){if(sim.tutorial){oldSummary();return;}closeStation();document.querySelector('.modal-backdrop')?.remove();modalKind=null;paused=true;document.body.classList.remove('playing');const r=sim.report();if(!sim.recorded){journey.reports.push(r);journey.cash=Math.max(0,journey.cash+r.profit);sim.recorded=true;}showReport();};
const metricRows=[['satisfaction','Customer satisfaction','%',true],['quality','Order quality','%',true],['profit','Shift profit','$',true],['queue','Average queue length','',false]];
function valueText(r,k,unit){return unit==='$'?'$'+r[k].toFixed(2):r[k].toFixed(k==='queue'?1:0)+unit;}
function progressReview(){
 const current=journey.reports.at(-1),previous=journey.reports.find(r=>r.shift===current.shift-1);
 const rows=[['served','Customers served','',true],['satisfaction','Customer satisfaction','%',true],['quality','Order quality','%',true],['returns','Remakes','',false],['profit','Profit','$',true]];
 const number=(r,k)=>Number(r[k]||0),format=(r,k,u)=>u==='$'?'$'+number(r,k).toFixed(2):number(r,k).toFixed(0)+u;
 function change(k,u,higher){if(!previous)return '<span class="progress-baseline">Starting point</span>';const d=number(current,k)-number(previous,k),amount=u==='$'?Math.abs(d).toFixed(2):Math.abs(d).toFixed(0);if(+amount===0)return '<span class="progress-neutral">No change</span>';const better=higher?d>0:d<0;const text=k==='served'?`${amount} ${d>0?'more':'fewer'} customer${+amount===1?'':'s'} served`:k==='returns'?`${amount} ${d>0?'more':'fewer'} remake${+amount===1?'':'s'}`:u==='%'?`${amount} percentage points ${d>0?'higher':'lower'}`:`$${amount} ${d>0?'more':'less'} profit`;return `<span class="progress-change ${better?'improved':'needs-attention'}">${better?'↑':'!'} ${text}</span>`;}
 return `<section class="progress-review" aria-labelledby="progress-title"><h2 id="progress-title">Your progress</h2><p class="progress-subtitle">${current.shift===1?'Your starting point.':'Compared with your previous shift.'}</p><div class="progress-table-wrap"><table><thead><tr><th scope="col">Measure</th>${[1,2,3].map(n=>`<th scope="col" ${n===current.shift?'class="current-shift"':''}>Shift ${n}${n===current.shift?' · Now':''}</th>`).join('')}<th scope="col">${previous?'Change from Shift '+previous.shift:'Baseline'}</th></tr></thead><tbody>${rows.map(([k,label,u,higher])=>`<tr><th scope="row">${label}</th>${[1,2,3].map(n=>{const r=journey.reports.find(r=>r.shift===n);return `<td ${n===current.shift?'class="current-shift"':''}>${r?format(r,k,u):'<span class="not-played">Not played</span>'}</td>`;}).join('')}<td>${change(k,u,higher)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
function showReport(){const r=journey.reports.at(-1);app.innerHTML=`<main class="shift-report"><small>rISE CAFÉ · SHIFT ${r.shift} OF 3</small><h1>${['','Learning & Observing','Improving the System','Testing & Optimizing'][r.shift]}</h1><h2>Shift results</h2><div class="report-cards"><div><b>${r.served}/${r.arrived}</b><span>Customers served</span></div><div><b>${r.maxQueue}</b><span>Longest queue</span></div><div><b>$${r.tips.toFixed(2)}</b><span>Tips</span></div><div><b>$${journey.cash.toFixed(2)}</b><span>Available budget</span></div></div><table class="shift-measures"><thead><tr><th>Measure</th><th>This shift</th></tr></thead><tbody>${metricRows.map(([k,label,unit])=>`<tr><td>${label}</td><td>${valueText(r,k,unit)}</td></tr>`).join('')}</tbody></table>${progressReview()}<div class="report-actions">${r.shift<3?`<button class="big-btn" id="go-shop">${r.shift===1?'Choose power-ups':'Review improvements'} →</button>`:'<button class="big-btn" id="restart-campaign">Play a new journey</button>'}<button class="big-btn gold" id="report-home">Welcome screen</button></div></main>`;document.querySelector('#go-shop')?.addEventListener('click',()=>{shopSelected='syrup';showShop();});document.querySelector('#restart-campaign')?.addEventListener('click',start);document.querySelector('#report-home').onclick=roles;}
function powerIcon(u){if(['syrup','milk','coffee'].includes(u.icon))return ingredientIcon(u.icon,{syrup:'Caramel',milk:'Oat Milk',coffee:'Original Blend'}[u.icon]);if(u.icon==='guide')return '<svg viewBox="0 0 100 90"><path d="M22 12h56l-8 68H30z" fill="#fff7e7" stroke="#71452d" stroke-width="4"/><path d="M30 52h40v22H33z" fill="#cb8643"/><path d="M15 45h70" stroke="#26ab53" stroke-width="5" stroke-dasharray="7 4"/></svg>';if(u.icon==='helper')return '<svg viewBox="0 0 100 90"><circle cx="50" cy="30" r="20" fill="#f2be8a" stroke="#71452d" stroke-width="3"/><path d="M17 88V65q33-32 66 0v23" fill="#518369" stroke="#71452d" stroke-width="3"/><path d="M29 23q0-28 42 0z" fill="#fff7df"/><path d="M40 36q10 10 20 0" fill="none" stroke="#71452d" stroke-width="3"/></svg>';if(u.icon==='display')return '<svg viewBox="0 0 100 90"><rect x="20" y="8" width="60" height="75" rx="6" fill="#fff7df" stroke="#71452d" stroke-width="4"/><path d="M30 25h40M30 39h40M30 53h40M30 67h28" stroke="#b9956b" stroke-width="5"/><path d="M60 59l7 8 14-19" fill="none" stroke="#27a855" stroke-width="5"/></svg>';if(u.icon==='layout')return '<svg viewBox="0 0 100 90"><g fill="#ecc58c" stroke="#71452d" stroke-width="3"><rect x="8" y="15" width="25" height="40" rx="5"/><rect x="67" y="15" width="25" height="40" rx="5"/></g><path d="M34 70h32m-24-8-8 8 8 8m16-16 8 8-8 8" fill="none" stroke="#30a657" stroke-width="5"/></svg>';return `<svg viewBox="0 0 100 90"><rect x="8" y="10" width="84" height="70" rx="9" fill="#777c89" stroke="#343440" stroke-width="4"/><rect x="16" y="25" width="60" height="42" fill="#402a23"/><rect x="17" y="25" width="55" height="42" rx="4" fill="#edb254"/><path d="M20 45h48${u.icon==='capacity'?'M20 56h48':''}" stroke="#755039" stroke-width="3"/><circle cx="82" cy="35" r="5" fill="#b9de96"/><path d="M23 18h45" stroke="#eee" stroke-width="4"/></svg>`;}
function preview(u){let scene='';if(['syrup','milk','coffee'].includes(u.icon))scene='<div class="demo-cup"><i></i></div><div class="demo-stream"></div>';else if(u.icon==='capacity')scene='<div class="demo-slots"><i>1</i><i>2</i><i>3</i></div>';else if(u.icon==='oven')scene='<div class="demo-clock">12s <span>✓ Ready</span></div>';else if(u.icon==='helper')scene='<div class="demo-second">'+powerIcon(u)+'</div>';else if(u.icon==='display')scene='<div class="demo-match">✓ Correct ingredient</div>';else if(u.icon==='layout')scene='<div class="demo-path">Order → Pour → Serve</div>';else scene='<div class="demo-match">✓ Inside target range</div>';return `<div class="power-demo demo-${u.icon}" aria-label="Animated illustration of ${u.name}">${powerIcon(u)}${scene}<span>${u.icon==='oven'?'20s → 12s':u.icon==='capacity'?'2 slots → 3 slots':u.icon==='layout'?'1.5s → 0.3s':u.icon==='helper'?'One worker → two':u.icon==='guide'?'Aim inside the green band':u.icon==='display'?'Match the ticket':'+35% flow speed'}</span></div>`;}
function showShop(){document.body.classList.remove('playing');const u=POWERUPS.find(u=>u.id===shopSelected),owned=u.rental?journey.rental:journey.owned.includes(u.id),afford=journey.cash>=u.cost;app.innerHTML=`<main class="power-screen"><section class="power-tablet" aria-label="Process improvement power-ups"><div class="power-catalog"><header><small>BEFORE SHIFT ${journey.shift+1} · PROCESS IMPROVEMENT</small><h1>Power Ups!</h1><span class="shop-wallet">Budget <b>$${journey.cash.toFixed(2)}</b></span></header><div class="power-grid">${POWERUPS.map(p=>`<button class="power-tile ${p.id===u.id?'selected':''}" data-power="${p.id}" aria-pressed="${p.id===u.id}"><div>${powerIcon(p)}</div><b>${p.name}</b><small>${(p.rental?journey.rental:journey.owned.includes(p.id))?'✓ '+(p.rental?'Reserved':'Owned'):'$'+p.cost+(p.rental?' / shift':'')}</small></button>`).join('')}</div></div><aside class="power-detail"><h2>${u.name}</h2>${preview(u)}<p>${u.benefit}</p><dl><dt>Strength</dt><dd>${u.strength}</dd><dt>Weakness</dt><dd>${u.weakness}</dd></dl><button class="big-btn buy-power" id="buy-power" ${owned||!afford?'disabled':''}>${owned?(u.rental?'✓ Reserved for next shift':'✓ Owned'):afford?'Buy · $'+u.cost:'Need $'+(u.cost-journey.cash).toFixed(2)+' more'}</button><small>${u.rental?'One-shift purchase; staffing appears in shift profit.':'Permanent for the remaining shifts in this journey.'}</small></aside><footer class="power-footer"><button id="back-report" class="big-btn gold">← Results</button><p>Pick the improvements that address your café’s problem.</p><button id="begin-next" class="big-btn">Start Shift ${journey.shift+1} →</button></footer></section></main>`;document.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>{shopSelected=b.dataset.power;showShop();});document.querySelector('#buy-power').onclick=()=>{if((u.rental?journey.rental:journey.owned.includes(u.id))||journey.cash<u.cost)return;if(u.rental){journey.rental=true;journey.cash-=u.cost;}else{journey.owned.push(u.id);journey.cash-=u.cost;}showShop();};document.querySelector('#back-report').onclick=showReport;document.querySelector('#begin-next').onclick=()=>{journey.shift++;if(journey.rental)journey.cash+=(journey.rentalCost||30);beginCampaignShift();};}
roles();
